// Optional same-origin backend. Static Sites deployments keep the original Demo.
let backendConfig=null,account=null,serverVersion=0,serverDay='',historyRows=[],syncTail=Promise.resolve(),syncCount=0,syncBroken=false;
const originalSave=save,originalToast=toast,uiRender=render,originalChat=chat;
async function api(route,method='GET',data){const response=await fetch('/api/'+route,{method,credentials:'same-origin',headers:{...(data?{'Content-Type':'application/json'}:{}),...(account?{'X-CSRF-Token':account.csrf}:{})},body:data?JSON.stringify(data):undefined});let result;try{result=await response.json()}catch{throw Error('服务响应异常，请稍后重试')}if(!response.ok){const error=Error(result.error||'请求未完成');error.status=response.status;throw error}return result}
function useAccount(data){account={username:data.username,csrf:data.csrf,aiConsent:data.aiConsent};state=data.state;serverVersion=data.version;serverDay=data.day;historyRows=data.history||[];syncBroken=false}
function cleanState(){return {done:[],water:0,goal:'提升力量与线条',minutes:'25',adjusted:false,meal:0}}
function setSync(text){const el=document.getElementById('sync-status');if(el)el.textContent=text}
save=function(){if(!backendConfig)return originalSave();if(!account){state=cleanState();authDialog();return Promise.resolve(false)}if(syncBroken){originalToast('同步已暂停，请在账户页重新载入云端记录');return Promise.resolve(false)}const snapshot=JSON.parse(JSON.stringify(state));syncCount++;setSync('正在同步…');syncTail=syncTail.then(async()=>{if(syncBroken)return false;try{const result=await api('state','PUT',{state:snapshot,version:serverVersion,day:serverDay});serverVersion=result.version;serverDay=result.day;historyRows=[{day:result.day,...result.state},...historyRows.filter(x=>x.day!==result.day)];return true}catch(e){syncBroken=true;originalToast(e.message+'；本次未确认保存');return false}}).finally(()=>{syncCount--;setSync(syncBroken?'同步失败 · 请重新载入':syncCount?'正在同步…':'已保存到云端')});return syncTail};
toast=function(text){if(backendConfig&&syncCount&&/已|完成/.test(text))originalToast('正在保存，请留意云端同步状态');else originalToast(text)};
function authDialog(mode='login'){const isNew=mode==='register',recover=mode==='recover';show(`<h2>${isNew?'创建你的 FORMA 账户':recover?'使用恢复码重设密码':'登录你的塑形空间'}</h2><p class="note">${isNew?'成年用户内测版。使用用户名注册，无需手机号。':recover?'恢复成功后，旧登录与旧恢复码会失效。':'训练和记录会保存在你的账户中。'}</p><form id="auth-form"><label>用户名<input name="username" required minlength="4" maxlength="32" pattern="[a-zA-Z0-9_]+" autocomplete="username" placeholder="4–32 位字母、数字或下划线"></label><label>${recover?'新密码':'密码'}<input name="password" type="password" required minlength="12" maxlength="128" autocomplete="${isNew||recover?'new-password':'current-password'}" placeholder="至少 12 位"></label>${recover?'<label>恢复码<input name="recovery" required autocomplete="off"></label>':''}${isNew?'<label class="consent-check"><input type="checkbox" name="adult" required>我已年满 18 周岁</label><label class="consent-check"><input type="checkbox" name="consent" required>我已阅读并同意按<a href="privacy.html" target="_blank">数据保存说明</a>保存我的账户与行动记录</label>':''}<p id="auth-error" role="alert"></p><button class="primary" type="submit">${isNew?'创建账户':recover?'重设密码':'登录'}</button> <button type="button" onclick="closeModal()">取消</button></form><div class="row section"><button onclick="authDialog('${isNew?'login':'register'}')">${isNew?'已有账户，登录':'没有账户，注册'}</button><button onclick="authDialog('recover')">忘记密码</button></div>`);document.getElementById('auth-form').onsubmit=async function(e){e.preventDefault();const button=this.querySelector('[type=submit]');button.disabled=true;try{const data=await api(mode,'POST',{username:this.username.value,password:this.password.value,adult:!!this.adult?.checked,consent:!!this.consent?.checked,...(recover?{recovery:this.recovery.value}:{})});useAccount(data);closeModal();location.hash='home';render();if(data.recovery)show(`<h2>请保存你的账户恢复码</h2><p>这是找回账户的唯一凭据。只显示这一次，请保存到密码管理器，不要分享给他人。</p><textarea readonly style="width:100%;padding:15px" aria-label="账户恢复码">${esc(data.recovery)}</textarea><p class="note">本服务暂不支持邮件找回。</p><button class="primary" onclick="closeModal()">我已保存</button>`)}catch(err){document.getElementById('auth-error').textContent=err.message}finally{button.disabled=false}}}
function accountDialog(){if(!account)return authDialog();show(`<h2>账户与数据</h2><p>已登录：${esc(account.username)}</p><p id="sync-status">${syncBroken?'同步失败，需重新载入':syncCount?'正在同步…':'已保存到云端'}</p><div class="row"><button onclick="reloadCloud()">重新载入云端记录</button><button onclick="exportData()">导出我的数据</button></div><h3>AI 数据授权</h3><p class="note">服务商：${esc(backendConfig.aiProvider)}。开启后，自由对话消息会发送给该服务商；不发送账户密码或完整健康档案。对话不保存在本服务数据库中。AI 可能出错，不用于医疗诊断。</p><button onclick="changeAIConsent()">${account.aiConsent?'撤回 AI 消息授权':'同意发送消息给 AI 服务商'}</button><p class="note">${backendConfig.aiEnabled?'服务商已配置':'自由对话模型尚未配置；基础规则功能可用。'}</p><div class="row section"><button onclick="logout()">退出登录</button><button onclick="deleteDialog()">删除账户及记录</button><button onclick="closeModal()">关闭</button></div><p><a href="privacy.html" target="_blank">数据保存说明</a></p>`)}
async function reloadCloud(){try{await syncTail;useAccount(await api('me'));closeModal();render();originalToast('已重新载入云端版本')}catch(e){originalToast(e.message)}}
async function changeAIConsent(){try{await api('ai-consent','PUT',{allowed:!account.aiConsent});account.aiConsent=!account.aiConsent;accountDialog()}catch(e){originalToast(e.message)}}
async function exportData(){try{await syncTail;const value=await api('export');const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='forma-data.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){originalToast(e.message)}}
async function logout(){try{await syncTail;await api('logout','POST');account=null;state=cleanState();closeModal();location.hash='discover';render()}catch(e){originalToast(e.message)}}
function deleteDialog(){show('<h2>删除账户及记录</h2><p>这会删除当前服务数据库里的账户、登录会话和记录，无法撤销。备份中的副本最长保留 7 天后到期清理。</p><form id="delete-form"><label>输入当前密码确认<input name="password" type="password" required autocomplete="current-password"></label><p id="delete-error" role="alert"></p><button type="submit">永久删除我的账户</button> <button type="button" onclick="accountDialog()">取消</button></form>');document.getElementById('delete-form').onsubmit=async function(e){e.preventDefault();try{await syncTail;await api('account','DELETE',{password:this.password.value});account=null;state=cleanState();closeModal();location.hash='discover';render();originalToast('账户和在线记录已删除')}catch(e){document.getElementById('delete-error').textContent=e.message}}}
function realHealth(){const recent=historyRows.slice(0,30);return title('YOUR OWN RECORDS','看见真实的每一步。','仅展示你保存的记录；每天按北京时间归档。','<button onclick="measure()">＋ 记录腰围</button>')+`<div class="grid"><div class="card"><h2>最近记录的腰围</h2><p class="big">${state.waist?esc(state.waist)+' cm':'尚未记录'}</p><p class="note">这是最近一次填写的数值。日快照会沿用它，不代表每天重新测量。</p><button onclick="measure()">添加记录</button></div><div class="card"><h2>数据由你管理</h2><p>可以导出记录、更正目标、撤回 AI 授权或删除账户。</p><button onclick="accountDialog()">账户与数据设置</button></div></div><div class="card section"><h2>最近 30 个有记录的日期</h2>${recent.length?`<div style="overflow:auto"><table class="history-table"><thead><tr><th>日期</th><th>完成任务</th><th>饮水</th><th>训练感受</th><th>最近腰围</th></tr></thead><tbody>${recent.map(r=>`<tr><td>${esc(r.day)}</td><td>${r.done.length} / 3</td><td>${r.water} 杯</td><td>${esc(r.effort||'—')}</td><td>${esc(r.waist||'—')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">暂无记录。完成今天的一项行动后，这里会显示你的真实数据。</p>'}</div>`}
render=function(){uiRender();if(!backendConfig)return;const landingView=!location.hash||location.hash==='#discover';if(landingView){document.querySelectorAll('.hero-actions a,.navcta,.closing a').forEach(a=>{a.onclick=e=>{if(!account){e.preventDefault();authDialog()}}});return}const avatar=document.querySelector('.avatar');avatar.textContent=account?account.username.slice(0,1).toUpperCase():'登录';avatar.onclick=accountDialog;avatar.setAttribute('aria-label',account?'账户设置':'登录');document.querySelector('.live').innerHTML=`<button class="account-link" onclick="accountDialog()">${account?esc(account.username):'登录 / 注册'}</button>`;document.querySelector('.sidebottom small').textContent=account?'账户数据 · 云端保存':'请登录后保存记录';document.querySelector('footer span').textContent=backendConfig.aiEnabled?'内测版 · AI 建议需自行核实':'内测版 · 基础规则教练';if(!account){$('#view').innerHTML=title('YOUR PERSONAL SPACE','建立属于你的塑形空间。','登录后保存计划与行动记录。')+'<div class="card"><p>你的训练、饮食行动和围度记录只对你的账户开放。</p><button class="primary" onclick="authDialog()">登录 / 创建账户</button></div>';return}
const status=document.createElement('div');status.className='sync-line';status.innerHTML=`<span id="sync-status">${syncBroken?'同步失败，请打开账户重新载入':syncCount?'正在同步…':'已保存到云端'}</span><button onclick="accountDialog()">账户设置</button>`;$('#view').prepend(status);
if(page==='home'){document.querySelector('.topline h1').textContent=`嗨，${account.username}。今天，为自己动一动。`;document.querySelector('.topline .kicker').textContent=serverDay+' · 今日计划';const count=historyRows.filter(r=>r.day>=new Date(Date.now()-6*86400000).toISOString().slice(0,10)&&r.done.includes('move')).length;const stat=document.querySelectorAll('.stat')[1];stat.innerHTML=`近 7 天活动<strong>${count}<small> 天</small></strong><span>按你的真实打卡统计</span>`;document.querySelectorAll('.week .day').forEach(el=>{el.className='day';el.innerHTML=el.innerHTML.replace('✓','·').replace('●','·')});const weekly=document.querySelector('.week')?.parentElement;if(weekly)weekly.innerHTML='<h2>按自己的节奏坚持</h2><p class="note">这里不显示虚构打卡。你的历史记录可在身体趋势页查看。</p><a href="#health">查看真实记录 ↗</a>';const bubble=document.querySelector('.bubble');if(bubble&&!state.adjusted)bubble.textContent='今天从一个基础动作开始。训练内容仍为通用模板；有伤病、孕产或其他特殊情况时，请先咨询专业人员。';}
if(page==='health')$('#view').innerHTML=realHealth();if(page==='coach'){document.querySelector('.banner').textContent=backendConfig.aiEnabled?'基础调整由规则处理；自由对话由配置的 AI 服务商提供，仅在你授权后发送。':'基础规则教练已连接后端；自由对话模型尚未配置。';document.querySelector('.message').textContent='你好。可以告诉我今天的时间或精力状态，调整建议由你确认后生效。'}
};
chat=async function(q){if(!backendConfig)return originalChat(q);if(!account)return authDialog();q=q.trim();if(!q)return;const log=$('#chatlog');const msg=document.createElement('div');msg.className='message user';msg.textContent=q;log.append(msg);const reply=document.createElement('div');reply.className='message';reply.textContent='正在处理…';log.append(reply);try{const r=await api('coach','POST',{message:q});reply.textContent=r.answer;const label=document.createElement('small');label.style.display='block';label.textContent={ai:'AI 生成 · 仅供一般参考',rules:'基础规则建议',safety:'安全提示'}[r.source];reply.append(label);if(r.action){const button=document.createElement('button');button.textContent='查看并确认调整';button.onclick=()=>adapt(r.action);reply.append(button)}}catch(e){reply.textContent=e.message}log.scrollTop=log.scrollHeight};
(async()=>{try{const response=await fetch('/api/config');if(!response.ok)return;const c=await response.json();if(!c.backend)return;backendConfig=c;state=cleanState();try{useAccount(await api('me'))}catch(e){if(e.status!==401)originalToast('暂时无法加载账户，请稍后重试')}render()}catch{}})();
